#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: create a buffer with small size and known content
    buffer_t *buf = helper_create_buffer_with_size(5); // small buffer
    TEST_ASSERT_NOT_NULL(buf);

    // Fill buffer with "abc" (len=3), so 2 bytes left (including null terminator)
    strcpy(buf->data, "abc");

    // Prepare string to append
    const char *to_append = "XYZ";
    size_t append_len = 3; // will need to append 3 bytes

    // Calculate needed: prev = 3, needed = 3+3=6, but buf->len=5, so resize needed
    // Setup malloc failure for buffer_resize's realloc
    // helper_create_buffer_with_size(5): 2 allocations (struct + data)
    // buffer_append_n triggers buffer_resize, which calls realloc (1 more allocation)
    // So, fail after 2 allocations to hit the realloc in buffer_resize
    malloc_fail_after(2);

    int ret = buffer_append_n(buf, to_append, append_len);

    // Should fail due to resize failure
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Buffer content should remain unchanged
    helper_assert_buffer_content(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_failure);
    return UNITY_END();
}


